    10	/** The acquirer resends rows after a timeout; the same payment id must be counted once. */
    11	public final class PaymentDeduper {
    12	    private PaymentDeduper() {}
    13	
    14	    public static List<Payment> unique(List<Payment> payments) {
    15	        Set<String> seen = new LinkedHashSet<>();
    16	        List<Payment> out = new ArrayList<>();
    17	        for (Payment p : payments) {
    18	            if (seen.add(p.payId())) out.add(p);
    19	        }
    20	        return out;
    21	    }
    22	}
=== src/service/EarnPolicy.java
     1	package service;
     2	
     3	import domain.Grade;
     4	
     5	/** Points for one payment: grade rate in basis points, rounded down, capped per payment. */
     6	public final class EarnPolicy {
     7	    private final long capPerPayment;
     8	
     9	    public EarnPolicy(long capPerPayment) {
    10	        this.capPerPayment = capPerPayment;
    11	    }
    12	
    13	    public long points(long amount, Grade grade) {
    14	        if (amount <= 0) return 0;
    15	        long raw = Math.floorDiv(Math.multiplyExact(amount, (long) grade.bps()), 10_000L);
    16	        return Math.min(raw, capPerPayment);
    17	    }
    18	}
