     9	import java.util.Properties;
    10	
    11	/** conf/app.properties, overridable by -Dpoints.KEY, POINTS_KEY env vars, or {@link #with}. */
    12	public final class AppConfig {
    13	    private final Properties props = new Properties();
    14	    private final Map<String, String> overrides = new HashMap<>();
    15	
    16	    private AppConfig() {}
    17	
    18	    public static AppConfig load() {
    19	        return load(Path.of("conf", "app.properties"));
    20	    }
    21	
    22	    public static AppConfig load(Path file) {
    23	        AppConfig cfg = new AppConfig();
    24	        try (InputStream in = Files.newInputStream(file)) {
    25	            cfg.props.load(in);
    26	        } catch (IOException e) {
    27	            throw new IllegalStateException("cannot read config " + file, e);
    28	        }
    29	        return cfg;
    30	    }
    31	
    32	    public AppConfig with(String key, String value) {
    33	        AppConfig copy = new AppConfig();
    34	        copy.props.putAll(props);
    35	        copy.overrides.putAll(overrides);
    36	        copy.overrides.put(key, value);
    37	        return copy;
    38	    }
    39	
    40	    public String get(String key) {
    41	        if (overrides.containsKey(key)) return overrides.get(key);
    42	        String sys = System.getProperty("points." + key);
    43	        if (sys != null && !sys.isBlank()) return sys.trim();
    44	        String env = System.getenv("POINTS_" + key.toUpperCase().replace('.', '_'));
    45	        if (env != null && !env.isBlank()) return env.trim();
    46	        String v = props.getProperty(key);
    47	        if (v == null) throw new IllegalStateException("missing config key " + key);
    48	        return v.trim();
    49	    }
    50	
    51	    public Path ptsBin() { return Path.of(get("pts.bin")); }
    52	
    53	    public long ptsTimeoutSeconds() { return Long.parseLong(get("pts.timeoutSeconds")); }
    54	
    55	    public Path ptsHome() { return Path.of(get("pts.home")); }
    56	
    57	    public long capPerPayment() { return Long.parseLong(get("points.capPerPayment")); }
    58	
    59	    public String refPrefix() { return get("points.refPrefix"); }
    60	
    61	    public Path dataDir() { return Path.of(get("data.dir")); }
    62	}
=== src/infra/CsvFiles.java
     1	package infra;
     2	
     3	import domain.Grade;
     4	import domain.Member;
     5	import domain.Payment;
     6	
     7	import java.io.IOException;
     8	import java.nio.charset.StandardCharsets;
     9	import java.nio.file.Files;
    10	import java.nio.file.Path;
    11	import java.util.ArrayList;
    12	import java.util.List;
    13	
    14	/** Fixture/export readers. Values never contain commas. */
    15	public final class CsvFiles {
    16	    private CsvFiles() {}
    17	
    18	    public static List<Member> members(Path file) {
    19	        List<Member> out = new ArrayList<>();
    20	        for (String[] r : rows(file)) {
    21	            out.add(new Member(cell(r[0]), r[1], Grade.valueOf(r[2]), r[3]));
    22	        }
    23	        return out;
    24	    }
    25	
    26	    public static List<Payment> payments(Path file) {
    27	        List<Payment> out = new ArrayList<>();
    28	        for (String[] r : rows(file)) {
    29	            out.add(new Payment(r[0], cell(r[1]), r[2], Long.parseLong(r[3]), r[4]));
    30	        }
    31	        return out;
    32	    }
    33	
    34	    /**
    35	     * The acquirer's payment export is made for spreadsheets: member numbers that start
    36	     * with 0 are written as ="004512" so the spreadsheet keeps them as text.
    37	     */
    38	    static String cell(String raw) {
    39	        String s = raw.strip();
    40	        if (s.startsWith("=\"") && s.endsWith("\"") && s.length() >= 3) {
    41	            return s.substring(2, s.length() - 1);
    42	        }
    43	        if (s.length() >= 2 && s.startsWith("\"") && s.endsWith("\"")) {
    44	            return s.substring(1, s.length() - 1);
    45	        }
    46	        return s;
    47	    }
    48	
    49	    private static List<String[]> rows(Path file) {
    50	        try {
    51	            List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
    52	            List<String[]> rows = new ArrayList<>();
    53	            for (int i = 1; i < lines.size(); i++) {
    54	                String l = lines.get(i).strip();
    55	                if (!l.isEmpty()) rows.add(l.split(",", -1));
    56	            }
    57	            return rows;
    58	        } catch (IOException e) {
    59	            throw new IllegalStateException("cannot read " + file, e);
    60	        }
    61	    }
