     1	package infra;
     2	
     3	import java.io.IOException;
     4	import java.io.InputStream;
     5	import java.nio.charset.StandardCharsets;
     6	import java.nio.file.Files;
     7	import java.nio.file.Path;
     8	import java.util.ArrayList;
     9	import java.util.List;
    10	import java.util.concurrent.TimeUnit;
    11	
    12	/** Thin wrapper around the points vendor CLI (vendor/bin/ptsctl). One process per call. */
    13	public class PtsctlClient {
    14	    /** One line of the vendor history: entry number, our reference, points. */
    15	    public record HistoryRow(String entryNo, String ref, long points) {}
    16	
    17	    private final Path bin;
    18	    private final Path home;
    19	    private final long timeoutSeconds;
    20	
    21	    public PtsctlClient(Path bin, Path home, long timeoutSeconds) {
    22	        this.bin = bin;
    23	        this.home = home;
    24	        this.timeoutSeconds = timeoutSeconds;
    25	    }
    26	
    27	    /** Credits points to a member; returns the vendor entry number. */
    28	    public String earn(String memberNo, long points, String ref) {
    29	        return run(List.of("earn", "--mbr", mbr(memberNo), "--pt", Long.toString(points), "--ref", ref)).strip();
    30	    }
    31	
    32	    public long balance(String memberNo) {
    33	        String out = run(List.of("bal", mbr(memberNo))).strip();
    34	        String[] t = out.split("\\s+");
    35	        if (t.length != 2) throw new PtsException("unexpected bal reply: " + out);
    36	        return Long.parseLong(t[1]);
    37	    }
    38	
    39	    public List<HistoryRow> history(String memberNo) {
    40	        List<HistoryRow> rows = new ArrayList<>();
    41	        for (String line : run(List.of("hist", mbr(memberNo))).split("\n")) {
    42	            if (line.isBlank()) continue;
    43	            String[] f = line.split("\t");
    44	            if (f.length != 3) throw new PtsException("unexpected hist line: " + line);
    45	            rows.add(new HistoryRow(f[0], f[1], Long.parseLong(f[2])));
    46	        }
    47	        return rows;
    48	    }
    49	
    50	    /**
    51	     * Member number as the vendor must read it. A bare all-digit number is read as a number by
    52	     * `earn` (leading zeros dropped: 004512 is credited to 4512); the @ form keeps it as issued.
    53	     */
    54	    static String mbr(String memberNo) {
    55	        return "@" + memberNo;
    56	    }
    57	
    58	    private String run(List<String> args) {
    59	        List<String> cmd = new ArrayList<>();
    60	        cmd.add(bin.toString());
    61	        cmd.addAll(args);
    62	        try {
    63	            Files.createDirectories(home);
    64	            ProcessBuilder pb = new ProcessBuilder(cmd);
    65	            pb.environment().put("PTSCTL_HOME", home.toAbsolutePath().toString());
    66	            Process p = pb.start();
    67	            byte[] out;
    68	            byte[] err;
    69	            try (InputStream o = p.getInputStream(); InputStream e = p.getErrorStream()) {
    70	                out = o.readAllBytes();
    71	                err = e.readAllBytes();
    72	            }
    73	            if (!p.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
    74	                p.destroyForcibly();
    75	                throw new PtsException("timeout: " + String.join(" ", cmd));
    76	            }
    77	            if (p.exitValue() != 0) {
    78	                throw new PtsException("ptsctl failed [" + new String(err, StandardCharsets.UTF_8).strip() + "]: "
    79	                        + String.join(" ", cmd));
    80	            }
    81	            return new String(out, StandardCharsets.UTF_8);
    82	        } catch (IOException e) {
    83	            throw new PtsException("exec failed: " + e.getMessage());
    84	        } catch (InterruptedException e) {
    85	            Thread.currentThread().interrupt();
    86	            throw new PtsException("interrupted");
    87	        }
    88	    }
    89	
    90	    public static class PtsException extends RuntimeException {
    91	        public PtsException(String msg) {
    92	            super(msg);
    93	        }
    94	    }
    95	}
