    10	import java.time.LocalDate;
    11	import java.util.ArrayList;
    12	import java.util.List;
    13	import java.util.Optional;
    14	
    15	/**
    16	 * Daily earn run: every approved payment of a known member earns grade-rate
    17	 * points at the points vendor once. The vendor reference is prefix + payment id,
    18	 * so a re-run never earns twice.
    19	 */
    20	public class EarnBatchJob {
    21	    private final MemberDirectory members;
    22	    private final EarnPolicy policy;
    23	    private final EarnLedger ledger;
    24	    private final PtsctlClient pts;
    25	    private final String refPrefix;
    26	
    27	    public EarnBatchJob(MemberDirectory members, EarnPolicy policy, EarnLedger ledger, PtsctlClient pts,
    28	                        String refPrefix) {
    29	        this.members = members;
    30	        this.policy = policy;
    31	        this.ledger = ledger;
    32	        this.pts = pts;
    33	        this.refPrefix = refPrefix;
    34	    }
    35	
    36	    public RunResult run(LocalDate day, List<Payment> payments) {
    37	        int earned = 0;
    38	        int skipped = 0;
    39	        long total = 0;
    40	        List<String> unknown = new ArrayList<>();
    41	        for (Payment p : PaymentDeduper.unique(payments)) {
    42	            if (!p.approved() || ledger.contains(p.payId())) {
    43	                skipped++;
    44	                continue;
    45	            }
    46	            Optional<Member> m = members.find(p.memberNo());
    47	            if (m.isEmpty()) {
    48	                unknown.add(p.memberNo());
    49	                continue;
    50	            }
    51	            long pts = policy.points(p.amount(), m.get().grade());
    52	            if (pts == 0) {
    53	                skipped++;
    54	                continue;
    55	            }
    56	            String entryNo = this.pts.earn(m.get().memberNo(), pts, refPrefix + "-" + p.payId());
    57	            ledger.record(new EarnEntry(p.payId(), m.get().memberNo(), pts, day, entryNo));
    58	            earned++;
    59	            total += pts;
    60	        }
    61	        return new RunResult(earned, total, List.copyOf(unknown), skipped);
    62	    }
    63	}
