package service;

import domain.Member;
import infra.PtsctlClient;

import java.util.regex.Pattern;

/**
 * Customer-care compensation (보상·수기 조정). Credited at the vendor with the reference
 * A-<ticket>, never the E- prefix of payment earns, and never recorded in our earn ledger,
 * so it stays out of the monthly top-earners list and the payment reconciliation.
 * The vendor accepts a reference once per ledger, which is what stops a double payout.
 */
public class CompensationService {
    static final String REF_PREFIX = "A-";
    private static final Pattern TICKET = Pattern.compile("[A-Za-z0-9-]{1,30}");

    private final MemberDirectory members;
    private final PtsctlClient pts;

    public CompensationService(MemberDirectory members, PtsctlClient pts) {
        this.members = members;
        this.pts = pts;
    }

    /** Returns the vendor entry number. Refuses unknown members and non-positive points before any credit. */
    public String compensate(String memberNo, long points, String ticketNo) {
        Member m = members.find(memberNo).orElseThrow(() -> new IllegalArgumentException("unknown member " + memberNo));
        if (points <= 0) throw new IllegalArgumentException("compensation must be positive: " + points);
        if (ticketNo == null || !TICKET.matcher(ticketNo).matches()) {
            throw new IllegalArgumentException("bad ticket number: " + ticketNo);
        }
        return pts.earn(m.memberNo(), points, REF_PREFIX + ticketNo);
    }
}

